import re

FORBIDDEN_REGEX = re.compile(
    r'[\u2010\u2011\u2012\u2013\u2014\u2015\u2043\u2212\u00A0\u00AD\u200B-\u200F\u202F\u2060\uFEFF]|--'
)
ASCII_WHITELIST = set(range(0x09, 0x0A+1)) | set(range(0x0D, 0x0D+1)) | set(range(0x20, 0x7E+1))

def hybrid_hygiene_scan(text):
    forbidden = [ (m.group(), m.start()) for m in FORBIDDEN_REGEX.finditer(text) ]
    ascii_viol = [ (c, i, ord(c)) for i, c in enumerate(text) if ord(c) not in ASCII_WHITELIST ]
    return {'forbidden': forbidden, 'ascii_violations': ascii_viol}

# Usage: call hybrid_hygiene_scan(text) for every user-facing field in Section4/5. Pass only if both lists are empty.

